const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((v) => resolve(v), (err) => reject(err));
  });
}

function fmt(x) {
  if (x === null || x === undefined || isNaN(x)) return 'null';
  return Number(x).toExponential(3);
}

async function computeMonthlyMeanPM25(params) {
  const {datasetId, bandCandidates, startDate, endDate, region, scale} = params;

  // Build initial collection
  let col = ee.ImageCollection(datasetId)
    .filterDate(ee.Date(startDate), ee.Date(endDate))
    .filterBounds(region);

  let size = await getInfoAsync(col.size());
  let usedStart = startDate;
  let usedEnd = endDate;

  // Recovery attempt: widen date by ±7 days if empty
  if (size === 0) {
    const widenedStart = ee.Date(startDate).advance(-7, 'day');
    const widenedEnd = ee.Date(endDate).advance(7, 'day');
    col = ee.ImageCollection(datasetId)
      .filterDate(widenedStart, widenedEnd)
      .filterBounds(region);
    size = await getInfoAsync(col.size());
    usedStart = await getInfoAsync(widenedStart.format('YYYY-MM-dd'));
    usedEnd = await getInfoAsync(widenedEnd.format('YYYY-MM-dd'));
  }

  if (size === 0) {
    return {status: 'C1', size, usedStart, usedEnd, band: null, mean: null, count: 0};
  }

  // Determine band
  const first = ee.Image(col.first());
  const bands = await getInfoAsync(first.bandNames());
  let selBand = null;
  for (const cand of bandCandidates) {
    if (bands.includes(cand)) { selBand = cand; break; }
  }
  if (!selBand) {
    // Try a looser match by substring
    const lowerBands = bands.map(b => String(b).toLowerCase());
    const guessedIdx = lowerBands.findIndex(b => b.includes('pm2') || b.includes('pm25') || b.includes('particulate'));
    if (guessedIdx >= 0) selBand = bands[guessedIdx];
  }
  if (!selBand) {
    return {status: 'D', size, usedStart, usedEnd, band: null, mean: null, count: 0};
  }

  const img = col.select(selBand).mean().rename('pm25');
  const countDict = img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  });
  const meanDict = img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
  });

  const count = await getInfoAsync(countDict.get('pm25'));
  if (!count || count === 0) {
    return {status: 'C2', size, usedStart, usedEnd, band: selBand, mean: null, count: 0};
  }
  const mean = await getInfoAsync(meanDict.get('pm25'));
  if (mean === null || mean === undefined || isNaN(mean)) {
    return {status: 'C3', size, usedStart, usedEnd, band: selBand, mean: null, count};
  }

  return {status: 'OK', size, usedStart, usedEnd, band: selBand, mean, count};
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const wuhan = ee.Geometry.Point([114.3055, 30.5928]);
    const region = wuhan.buffer(30000); // ~30 km buffer
    const scale = 30000; // coarse model grid scale
    const datasetId = 'ECMWF/CAMS/NRT'; // CAMS near-real-time atmospheric composition
    const bandCandidates = [
      'pm2p5', 'particulate_matter_2p5um', 'particulate_matter_2p5',
      'pm2p5_surface', 'pm2p5_sfc', 'pm2p5_conc'
    ];

    const feb2019 = await computeMonthlyMeanPM25({
      datasetId,
      bandCandidates,
      startDate: '2019-02-01',
      endDate: '2019-03-01',
      region,
      scale
    });

    const feb2020 = await computeMonthlyMeanPM25({
      datasetId,
      bandCandidates,
      startDate: '2020-02-01',
      endDate: '2020-03-01',
      region,
      scale
    });

    console.log(`Dataset: ${datasetId}`);
    console.log(`Area: Wuhan (30 km buffer). Scale: ${scale} m`);
    console.log(`Band (2019 guess): ${feb2019.band}`);
    console.log(`Band (2020 guess): ${feb2020.band}`);

    // Handle error statuses
    if (feb2019.status === 'D' || feb2020.status === 'D') {
      console.log('Status: Band or dataset issue.');
      console.log('D');
      return;
    }
    if (feb2019.status === 'C1' || feb2020.status === 'C1') {
      console.log(`2019 Images: ${feb2019.size} | 2020 Images: ${feb2020.size}`);
      console.log('C1');
      return;
    }
    if (feb2019.status === 'C2' || feb2020.status === 'C2') {
      console.log(`2019 Valid px: ${feb2019.count} | 2020 Valid px: ${feb2020.count}`);
      console.log('C2');
      return;
    }
    if (feb2019.status === 'C3' || feb2020.status === 'C3') {
      console.log(`2019 Mean: ${fmt(feb2019.mean)} | 2020 Mean: ${fmt(feb2020.mean)}`);
      console.log('C3');
      return;
    }

    console.log(`2019 Feb Images: ${feb2019.size} [${feb2019.usedStart}..${feb2019.usedEnd}]`);
    console.log(`2019 Valid px: ${feb2019.count}, Mean: ${fmt(feb2019.mean)}`);
    console.log(`2020 Feb Images: ${feb2020.size} [${feb2020.usedStart}..${feb2020.usedEnd}]`);
    console.log(`2020 Valid px: ${feb2020.count}, Mean: ${fmt(feb2020.mean)}`);

    const diff = feb2020.mean - feb2019.mean;
    console.log(`Delta (2020-2019): ${fmt(diff)}`);

    if (!isFinite(diff)) {
      console.log('C3');
      return;
    }

    // Final answer: "Was PM2.5 higher in Feb 2020 than in Feb 2019?"
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : String(err)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
